async function registryData(){const original=cp(FIX.plain.registry),reverse=new Map(original.records.map(r=>[r.id,r.key]));const records=original.records.map(r=>{const v=cp(r);delete v.id;for(const k of ['source_chain','source_refs','alternative_refs'])if(k in v)v[k]=v[k].map(id=>reverse.get(id));return v;});const plan={contract:'owner-financial-key-plan-v2',parser_revision:'owner-financial-csv-v1',records},csv='synthetic-only CSV snapshot',csvSha=await api.sha(csv),planSha=await api.hash(plan),binding={contract:'financial-input-v2',parser_revision:'owner-financial-csv-v1',research_id:rid,input_revision:1,problem_digest:original.binding.problem_digest,expected_research_version:1,exact_received_csv_sha256:csvSha,key_based_plan_digest:planSha},preview=await api.hash(binding);original.format_version='owner-financial-registry-public-v2';delete original.receipt.received_ref;Object.assign(original.receipt,{exact_received_csv_sha256:csvSha,key_based_plan_digest:planSha,preview_digest:preview});const projection={csv_text:csv,registry:original},operation={schema_version:'structure-research-v1',contract_revision:'financial-input-v2',data:{input_revision:1,expected_research_version:1,csv_text:csv,preview_digest:preview,confirmed:true}},metadata={...original.binding,registry_ref:cp(FIX.plain.operation.data.registry_ref),...original.receipt,parser_revision:original.parser_revision,request_digest:await api.hash(operation),qualification:'conditional_on_owner_supplied_data',kind:'owner_supplied',verification:'unverified',original_available:false,system_verified:false};return {metadata,current:{input_revision:1,research_version:2},is_historical:false,projection,public_projection_digest:await api.hash(projection),execution_authorized:false};}
function complete(data){const f=api.draft(),r=data.projection.registry.records.find(r=>r.row_type==='observation'&&r.metric==='revenue');f.baseline=r.id;f.entity_scope=r.entity_scope;f.cutoff='2026-10-17';f.reason='合成基线选择理由';f.target_currency=r.currency;f.categories_confirmed=true;for(const s of f.scenarios){s.label='条件演示';s.accounting_basis=r.accounting_basis;s.remaining.value='60';s.remaining.currency=r.currency;s.remaining.rationale='独立剩余期假设';for(const p of Object.values(s.growth)){p.value='10';p.rationale='独立增长假设';}}return f;}
class Element{constructor(tag='div',doc){this.tagName=tag.toUpperCase();this.doc=doc;this.children=[];this.text='';this.value='';this.checked=false;this.hidden=false;this.disabled=false;this.attrs={};this.events={};}set textContent(v){this.text=String(v);this.children=[];}get textContent(){return this.text+this.children.map(n=>typeof n==='string'?n:n.textContent).join('');}setAttribute(k,v){this.attrs[k]=v;if(k==='id')this.doc.elements.set(v,this);}getAttribute(k){return this.attrs[k]??null;}hasAttribute(k){return Object.hasOwn(this.attrs,k);}removeAttribute(k){delete this.attrs[k];}append(...v){this.children.push(...v);}replaceChildren(...v){this.text='';this.children=v;}addEventListener(k,fn){(this.events[k]||=[]).push(fn);}fire(k){return Promise.all((this.events[k]||[]).map(fn=>fn({target:this})));}querySelectorAll(tag){return this.children.flatMap(n=>typeof n==='string'?[]:[...(n.tagName.toLowerCase()===tag?[n]:[]),...n.querySelectorAll(tag)]);}}
function memory(){const values=new Map();return {values,get length(){return values.size;},key:i=>[...values.keys()][i]??null,getItem:k=>values.get(k)??null,setItem:(k,v)=>values.set(k,v),removeItem:k=>values.delete(k)};}
const html=fs.readFileSync(path.join(__dirname,'../research.html'),'utf8');
function runtime(data,sender,{storage=memory(),selected=true}={}){const doc={elements:new Map(),createElement(tag){return new Element(tag,this);},createElementNS(ns,tag){return new Element(tag,this);},createTextNode:v=>v,getElementById(id){return this.elements.get(id);}};for(const m of html.matchAll(/id="(financial-scenario-[^"]+)"/g))doc.elements.set(m[1],new Element('div',doc));for(const view of ['summary','table','chart']){const b=doc.createElement('button');b.setAttribute('data-view',view);doc.getElementById('financial-scenario-tabs').append(b);}const s={account:JSON.stringify(['scenario@example.invalid','2026-10-23']),privateGeneration:1,rid,revision:1,digest:data.metadata.problem_digest,version:2,visible:true,dirty:false,readonly:false,busy:false};let choice=selected?data:null,version=2,revision=1;const requests=[];
const controller=api.mount({document:doc,getScope:()=>({...s}),getSelectedRegistry:()=>choice,authenticate:async active=>active(),fetchRoot:async()=>({research:{id:rid,current_revision:revision},research_version:version,revisions:Array.from({length:revision},(_,i)=>({revision:i+1,digest:data.metadata.problem_digest}))}),storage,fetch:async(url,options)=>{requests.push({url,options});return sender(url,options);}});return {controller,scope:s,storage,requests,doc,el:k=>doc.getElementById('financial-scenario-'+k),setChoice:v=>choice=v,setRoot:(v,r=1)=>{version=v;revision=r;}};}
