test('three real schema canonical byte hashes and source binding',async()=>{for(const [name,s] of Object.entries(api.SCHEMAS)){const raw=api.canonical(s)+'\n';assert.equal(Buffer.byteLength(raw),api.EXPORTS[name].bytes);assert.equal(await api.sha(raw),api.EXPORTS[name].sha256);}assert.equal(crypto.createHash('sha256').update(fs.readFileSync(path.join(__dirname,'../../backend/research/financial_result_v2.py'))).digest('hex'),api.SOURCE_SHA256);});

test('fresh instances and add/remove histories rebuild identical hidden IDs and sensitivity mapping',async()=>{const data=await registryData(),a=complete(data);a.sensitivity={scenario:0,target:'growth:2027',points:'0,10,20'};const b=cp(a);b.scenarios.push(api.scenario());b.scenarios.pop();b.categories.unshift({label:'temporary',definition:'temporary',kind:'segment'});b.categories.shift();b.scenarios[0].costs.push({temporary:true});b.scenarios[0].costs.pop();const one=api.compile(a,data,scope),two=api.compile(b,data,scope);assert.equal(api.canonical(one),api.canonical(two));assert.equal(two.data.request.sensitivity.parameter_id,'growth_2027');assert.equal(two.data.request.scenarios[0].growth[0].parameter.value,'0.1');assert.deepEqual(two.data.request.derived_fx_inputs,[]);});

test('all three scenarios and 21 independent points, null and coverage remain explicit',async()=>{const data=await registryData(),f=complete(data);f.scenarios=[cp(f.scenarios[0]),cp(f.scenarios[0]),cp(f.scenarios[0])];f.scenarios[2].growth[2031].value='';f.sensitivity={scenario:2,target:'growth:2027',points:Array.from({length:21},(_,i)=>String(i)).join(',')};const op=api.compile(f,data,scope);assert.equal(op.data.request.scenarios.length,3);assert.equal(op.data.request.sensitivity.points.length,21);assert.equal(op.data.request.scenarios[2].growth[4].parameter.value,null);assert.deepEqual(op.data.request.scenarios[0].costs,[]);assert.equal(op.data.request.sensitivity.scenario_id,'scenario_3');});

test('cost coverage, refs, dates, unit and reason failures do not silently invent values',async()=>{const data=await registryData();for(const mutate of [f=>f.reason='',f=>f.cutoff='2025-01-01',f=>f.scenarios[0].growth[2027].value='-101',f=>f.categories_confirmed=false,f=>f.scenarios[0].remaining.source_refs=['bad'],f=>f.scenarios[0].remaining.rationale='',f=>f.scenarios[0].costs.push({kind:'operating_cost',label:'成本',mode:'amount',coverage:[],coverage_basis:'缺覆盖',values:{}})]){const f=complete(data);mutate(f);assert.throws(()=>api.compile(f,data,scope));}const f=complete(data);f.scenarios[0].costs.push({kind:'operating_cost',label:'全成本',mode:'revenue_ratio',coverage:['base_operating_cost','base_operating_expense','shared_cost','depreciation','sbc'],coverage_basis:'明确全含',values:{2026:{...api.parameter('ratio'),value:'120',rationale:'亏损条件'}}});assert.equal(api.compile(f,data,scope).data.request.scenarios[0].costs[0].values[0].parameter.value,'1.2');});

test('input decimal conversion and display half-even preserve null, zeros and tiny computed values',()=>{assert.equal(api.value('10',true),'0.1');assert.equal(api.value('',true),null);assert.equal(api.value('0'), '0');assert.equal(api.display('1.2345665'),'1.234566');assert.equal(api.display('1.2345675'),'1.234568');assert.equal(api.display('1E-100'),'0.000000');assert.equal(api.display(null),null);for(const v of ['NaN','1,000','1e999','1000000000000000001'])assert.throws(()=>api.value(v));});

test('actual pure projected summary/table/chart including old derived daily evidence validate',async()=>{for(const fixture of Object.values(FIX))for(const view of ['summary','table','chart'])assert.equal((await api.check('result',fixture.views[view],{rid:fixture.registry.binding.research_id,ref,view})).public_result.view,view);assert.equal(FIX.derived.views.table.data.public_result.value.evidence.derived_fx_evidence[0].input.points.length,129);});

test('outer hash/union/ref/snapshot anchor/provenance and false-flag tampering is rejected',async()=>{for(const mutate of [v=>v.data.metadata.result_ref='bad',v=>v.data.persisted=1,v=>v.data.metadata.model_analysis_ran=0,v=>v.data.public_result.view='chart',v=>v.data.public_result.value.scenarios[0].years[0].target.revenue.raw_value='123',v=>v.data.public_result.value.evidence.provenance_table.find(p=>p.source_refs.length).source_refs=[]]){const v=cp(FIX.plain.views.table);mutate(v);await assert.rejects(api.check('result',v,{rid,ref,view:'table'}));}const v=cp(FIX.plain.views.chart);v.data.public_result.value.chart_spec.connect_nulls=true;v.data.public_result_digest=await api.hash(v.data.public_result);await assert.rejects(api.check('result',v,{rid,ref,view:'chart'}));});

test('new operation double click locks and stores only bounded metadata, never raw input/body',async()=>{const data=await registryData();let release,started;const began=new Promise(r=>started=r);const r=runtime(data,()=>new Promise(done=>{release=()=>done(new Response('bad'));started();}));await r.controller.adopt();r.controller.setDraft(complete(data));r.el('consent').checked=true;const waiting=r.controller.calculate();await began;await r.controller.calculate();release();await waiting;assert.equal(r.requests.length,1);assert.equal(r.controller.inspect().pending,true);assert.equal(r.storage.values.size,1);const raw=[...r.storage.values.values()][0];assert.ok(Buffer.byteLength(raw)<=2048);assert.doesNotMatch(raw,/合成基线选择理由|独立增长假设|request"|body"|csv_text|scenario@example/);});

test('initial verified actor activation restores pending without first click, confirmed loss only clears own namespace',async()=>{const data=await registryData(),store=memory(),one=runtime(data,()=>{throw new TypeError('lost');},{storage:store});await one.controller.adopt();one.controller.setDraft(complete(data));one.el('consent').checked=true;await one.controller.calculate();store.setItem('structure-research-pending:other-module','keep');const two=runtime(data,()=>{throw Error('no request');},{storage:store});two.controller.observe();assert.equal(two.controller.inspect().pending,false);await two.controller.activateVerifiedAccount(two.scope.account,()=>true);assert.equal(two.controller.inspect().pending,true);assert.match(two.el('pending').textContent,/原表单未保留/);two.controller.reset('confirmed_logout');assert.deepEqual([...store.values.entries()],[['structure-research-pending:other-module','keep']]);});

test('explicit historical recovery catalog never selects FIN2 or enables a new calculation',async()=>{const data=await registryData(),store=memory(),one=runtime(data,()=>{throw new TypeError('lost');},{storage:store});await one.controller.adopt();one.controller.setDraft(complete(data));one.el('consent').checked=true;await one.controller.calculate();const historic=cp(data);historic.current={input_revision:2,research_version:8};historic.is_historical=true;const envelope={schema_version:'structure-research-v1',contract_revision:'financial-input-v2',data:historic};const two=runtime(data,()=>response(envelope),{storage:store,selected:false});two.scope.revision=2;two.scope.version=8;two.setRoot(8,2);await two.controller.activateVerifiedAccount(two.scope.account,()=>true);await two.controller.readRecoveryMaterial();assert.equal(two.controller.inspect().hasRecoveryCatalog,true);assert.equal(two.controller.inspect().mode,'recovery');assert.equal(two.controller.inspect().hasAdopted,false);two.controller.setDraft(complete(data));two.el('consent').checked=true;await two.controller.calculate();assert.equal(two.requests.filter(x=>x.options.method==='POST').length,0);assert.equal(two.el('calculate').disabled,true);});

test('unknown/bfcache/navigation preserve key while clearing private catalogs/results; late binding cannot revive loss',async()=>{const data=await registryData();for(const cause of ['auth_unknown','bfcache_restore','inflight_navigation']){const r=runtime(data,()=>{throw new TypeError('lost');});await r.controller.adopt();r.controller.setDraft(complete(data));r.el('consent').checked=true;await r.controller.calculate();const before=[...r.storage.values.entries()];r.controller.invalidate(cause);assert.deepEqual([...r.storage.values.entries()],before);assert.equal(r.controller.inspect().hasRecoveryCatalog,false);assert.equal(r.controller.inspect().hasAdopted,false);assert.equal(r.el('result').textContent,'');}const r=runtime(data,()=>{throw Error('no fetch');});const late=r.controller.activateVerifiedAccount(r.scope.account,()=>true);r.controller.reset('confirmed_logout');assert.equal(await late,false);assert.equal(r.controller.inspect().pending,false);});


test('fresh form rebuild after reload posts byte-identical original body/key despite later revision and no current selection',async()=>{
 const data=await registryData(),store=memory(),first=runtime(data,()=>{throw new TypeError('lost');},{storage:store});await first.controller.adopt();const originalForm=complete(data);originalForm.sensitivity={scenario:0,target:'growth:2027',points:'0,10,20'};first.controller.setDraft(originalForm);first.el('consent').checked=true;await first.controller.calculate();const sent=first.requests.find(r=>r.options.method==='POST').options;const historic=cp(data);historic.current={input_revision:2,research_version:8};historic.is_historical=true;
 const second=runtime(data,(url,o)=>{if(o.method==='POST')throw new TypeError('owned replay observation lost');return response({schema_version:'structure-research-v1',contract_revision:'financial-input-v2',data:historic});},{storage:store,selected:false});second.scope.revision=2;second.scope.version=8;second.setRoot(8,2);await second.controller.activateVerifiedAccount(second.scope.account,()=>true);await second.controller.readRecoveryMaterial();const rebuilt=cp(originalForm);rebuilt.scenarios.push(api.scenario());rebuilt.scenarios.pop();second.controller.setDraft(rebuilt);await second.controller.recover();const replay=second.requests.find(r=>r.options.method==='POST').options;assert.equal(replay.body,sent.body);assert.equal(replay.headers['Idempotency-Key'],sent.headers['Idempotency-Key']);assert.equal(second.controller.inspect().hasAdopted,false);
});

test('late recovery catalog cannot return after actor loss or silently unlock a new calculation',async()=>{
 const data=await registryData(),store=memory(),first=runtime(data,()=>{throw new TypeError('lost');},{storage:store});await first.controller.adopt();first.controller.setDraft(complete(data));first.el('consent').checked=true;await first.controller.calculate();let ready,release;const began=new Promise(r=>ready=r);const second=runtime(data,()=>new Promise(done=>{release=()=>done(response({schema_version:'structure-research-v1',contract_revision:'financial-input-v2',data}));ready();}),{storage:store,selected:false});await second.controller.activateVerifiedAccount(second.scope.account,()=>true);const waiting=second.controller.readRecoveryMaterial();await began;second.controller.reset('actor_changed');release();await waiting;assert.equal(second.controller.inspect().hasRecoveryCatalog,false);assert.equal(second.controller.inspect().hasAdopted,false);assert.equal(second.el('calculate').disabled,true);assert.equal(store.values.size,0);
});

test('full operation cap rejects before key/body storage, no truncated parameter or implicit submit',async()=>{const data=await registryData(),f=complete(data);f.scenarios[0].costs=Array.from({length:16},(_,i)=>({kind:'operating_adjustment',label:'调整'+i,mode:'amount',coverage:[],coverage_basis:'独立调整，不占成本覆盖',values:Object.fromEntries([2026,2027,2028,2029,2030,2031].map(y=>[y,{...api.parameter('million','CNY'),value:'1',rationale:'界'.repeat(400)}]))}));assert.throws(()=>api.compile(f,data,scope),/64KiB/);const r=runtime(data,()=>{throw Error('must not post');});await r.controller.adopt();r.controller.setDraft(f);r.el('consent').checked=true;await r.controller.calculate();assert.equal(r.requests.length,0);assert.equal(r.storage.values.size,0);assert.equal(r.controller.inspect().pending,false);});

test('expanded editor remains open through structure changes and raw known zeros never become missing',async()=>{const data=await registryData(),r=runtime(data,()=>{throw Error('no request');});await r.controller.adopt();r.controller.setDraft(complete(data));const panel=r.el('sensitivity-panel');panel.setAttribute('open','');const toggle=r.el('sensitivity-enabled');toggle.checked=true;await toggle.fire('change');assert.equal(r.el('sensitivity-panel').hasAttribute('open'),true);const f=complete(data);f.scenarios[0].remaining.value='0';assert.equal(api.compile(f,data,scope).data.request.scenarios[0].remaining_revenue.value,'0');});


test('changing or invalidating FIN2 selection preserves the draft but immediately requires explicit adoption',async()=>{const data=await registryData(),r=runtime(data,()=>{throw Error('no post');});await r.controller.adopt();const f=complete(data);r.controller.setDraft(f);r.el('consent').checked=true;r.setChoice(null);r.controller.observeRegistrySelection();assert.equal(r.el('calculate').disabled,true);assert.deepEqual(r.controller.getDraft(),f);assert.match(r.el('status').textContent,/不会自动替换出处/);r.setChoice(data);await r.controller.adopt();assert.deepEqual(r.controller.getDraft(),f);assert.equal(r.requests.length,0);});
